<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $record->voucher_reference ?: $record->reference }} · {{ $title }}</title><link rel="stylesheet" href="/print.css"></head><body>
@php
    $subtotal = $records->sum('total_cents');
    $charges = (int)$record->labour_cents + (int)$record->commission_cents + (int)$record->freight_cents + (int)$record->other_charges_cents - (int)$record->discount_cents;
    $taxable = max(0, $subtotal + $charges);
    $gst = (int) round($taxable * ((float)$record->gst_percent) / 100);
    $grand = $taxable + $gst;
@endphp
<div class="print-actions"><button onclick="window.print()">Print / Save as PDF</button><button onclick="window.close()">Close</button></div>
<main class="paper receipt-paper"><header class="receipt-header"><div><small>Voucher No.</small><strong>{{ $record->voucher_reference ?: $record->reference }}</strong></div><h1>JSSC AZAD</h1><div><small>Goods / Vehicle No.</small><strong>{{ $record->goods_number ?: '—' }}</strong></div></header><section class="receipt-meta"><div><small>M/s.</small><strong>{{ $record->party }}</strong></div><div><small>B. Rate</small><strong>{{ number_format(($records->first()->base_rate_cents ?: $record->unit_price_cents)/100,2) }}</strong></div><div><small>Dated</small><strong>{{ date('d-m-Y', strtotime($record->date)) }}</strong></div></section><table class="print-table receipt-table"><thead><tr><th>Sr</th><th>Description</th><th>Diff.</th><th>B. Rate</th><th>Qty.</th><th>Rate</th><th>Amount</th></tr></thead><tbody>@foreach($records as $line)<tr><td>{{ $loop->iteration }}</td><td>{{ $line->product_name ?: $record->group_head_name }}</td><td class="num">{{ number_format($line->difference_cents/100,2) }}</td><td class="num">{{ number_format(($line->base_rate_cents ?: $line->unit_price_cents)/100,2) }}</td><td class="num">{{ number_format($line->quantity,3) }}</td><td class="num">{{ number_format($line->unit_price_cents/100,2) }}</td><td class="num">{{ number_format($line->total_cents/100,2) }}</td></tr>@endforeach @for($i=$records->count();$i<12;$i++)<tr class="blank"><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td></tr>@endfor</tbody><tfoot><tr><th colspan="4">Total Quantity</th><th class="num">{{ number_format($records->sum('quantity'),3) }}</th><th>Total</th><th class="num">{{ number_format($subtotal/100,2) }}</th></tr></tfoot></table><section class="receipt-bottom"><div class="average"><strong>AVG. {{ $records->sum('quantity') > 0 ? number_format(($subtotal/100)/$records->sum('quantity'),2) : '0.00' }}</strong><div class="charges"><span>Labour<br><b>{{ number_format($record->labour_cents/100,2) }}</b></span><span>Discount<br><b>{{ number_format($record->discount_cents/100,2) }}</b></span><span>Comm.<br><b>{{ number_format($record->commission_cents/100,2) }}</b></span><span>Freight<br><b>{{ number_format($record->freight_cents/100,2) }}</b></span><span>Others<br><b>{{ number_format($record->other_charges_cents/100,2) }}</b></span></div></div><table class="totals-box"><tr><th>Taxable</th><td>{{ number_format($taxable/100,2) }}</td></tr><tr><th>GST {{ number_format($record->gst_percent,2) }}%</th><td>{{ number_format($gst/100,2) }}</td></tr><tr class="grand"><th>G Total</th><td>{{ number_format($grand/100,2) }}</td></tr></table></section></main></body></html>
